package store

import (
	"context"
	"testing"
)

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	r := &MemReader{Err: ErrRetry}
	_, err := Fetch(ctx, r, "key")

	if got := r.Reads(); got != 1 {
		t.Fatalf("Fetch(cancelledCtx) reads = %d, want 1", got)
	}
	if err != context.Canceled {
		t.Fatalf("Fetch(cancelledCtx) error = %v, want %v", err, context.Canceled)
	}
}

