package recruiter

import (
	"context"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, key string) ([]byte, string, error) {
	if err := ctx.Err(); err != nil {
		return nil, "", err
	}
	return []byte(`{}`), "etag1", nil
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, key string, data []byte, ifMatch string) error {
	// Return an ETag mismatch unconditionally so Mutate enters its time.Sleep
	// backoff. We bypass ctx.Err() checks here to perfectly simulate the context
	// being cancelled concurrently exactly as the sleep starts.
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	s := &Store{
		Storage: &gsrFakeStorage{},
		Bucket:  "test-bucket",
	}

	attempts := 0
	_, _ = s.Mutate(ctx, "profile-1", func(c Contact) Contact {
		attempts++
		if attempts == 1 {
			cancel() // Cancel the context during the first attempt
		}
		return c
	})

	if attempts >= maxWriteRetries {
		t.Fatalf("Mutate(ctx) exhausted all %d retries despite cancelled context; expected early abort", attempts)
	}
}

