	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrFakeStorage struct {
	storage.Client
	writes int
}

func (f *gsrFakeStorage) ReadFile(ctx context.Context, bucket, name string) ([]byte, string, error) {
	return []byte(`{}`), "etag123", nil
}

func (f *gsrFakeStorage) WriteFile(ctx context.Context, bucket, name string, data []byte, ifMatch string) error {
	f.writes++
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // cancel immediately

	fs := &gsrFakeStorage{}
	store := &Store{Storage: fs, Bucket: "test-bucket"}

	_, _ = store.Mutate(ctx, "https://linkedin.com/in/jane", func(c Contact) Contact { return c })

	if fs.writes > 1 {
		t.Fatalf("WriteFile calls = %d, want <= 1", fs.writes)
	}
}

package recruiter

import (
	"context"
	"errors"
	"testing"

	"github.com/weitzer-org/job_tracker/internal/storage"
)

type gsrMockStorage struct {
	storage.Client
	writes int
	cancel context.CancelFunc
}

func (m *gsrMockStorage) ReadFile(ctx context.Context, bucket, objectKey string) ([]byte, string, error) {
	return []byte(`{}`), "etag", nil
}

func (m *gsrMockStorage) WriteFile(ctx context.Context, bucket, objectKey string, data []byte, ifMatch string) error {
	m.writes++
	if m.cancel != nil {
		m.cancel() // cancel the context during the first conflict write to simulate the race
		m.cancel = nil
	}
	return storage.ErrETagMismatch
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	m := &gsrMockStorage{cancel: cancel}
	s := &Store{
		Storage: m,
		Bucket:  "test-bucket",
	}

	_, err := s.Mutate(ctx, "profile1", func(c Contact) Contact { return c })

	if m.writes == maxWriteRetries {
		t.Fatalf("Store.Mutate ignored context cancellation during ETag mismatch backoff, made all %d attempts", m.writes)
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("Store.Mutate err = %v, want context.Canceled", err)
	}
}
